import{_ as i,o as t,c as r,a2 as a}from"./chunks/framework.BWuWLRhz.js";const c=JSON.parse('{"title":"クイック起動設定","description":"","frontmatter":{},"headers":[],"relativePath":"ja-JP/user-guide/settings/quick-launch.md","filePath":"ja-JP/user-guide/settings/quick-launch.md","lastUpdated":1788419640000}'),o={name:"ja-JP/user-guide/settings/quick-launch.md"};function n(s,l,e,g,u,d){return t(),r("div",null,[...l[0]||(l[0]=[a('<h1 id="クイック起動設定" tabindex="-1">クイック起動設定 <a class="header-anchor" href="#クイック起動設定" aria-label="Permalink to &quot;クイック起動設定&quot;">​</a></h1><p>クイック起動は、検索ボックスが空のときにクイック検索ウィンドウの下に表示される起動パネルです。手動で管理する項目と、お気に入りや履歴など選択した動的データソースを組み合わせて表示します。</p><h2 id="_1-マスタースイッチ" tabindex="-1">1. マスタースイッチ <a class="header-anchor" href="#_1-マスタースイッチ" aria-label="Permalink to &quot;1. マスタースイッチ&quot;">​</a></h2><ul><li><strong>クイック起動パネルを有効にする</strong>：パネルを有効にします。クイック検索ウィンドウの検索欄が空で、少なくとも1つのデータソースに利用可能なデータがある場合だけ表示されます。</li><li>無効にすると、パネルはデータソースを読み込みません。</li><li>パネルの高さは項目数が最も多いデータソースを基準に計算され、クイック検索ウィンドウの結果領域の最大高さを超えません。</li></ul><h2 id="_2-手動クイック起動項目" tabindex="-1">2. 手動クイック起動項目 <a class="header-anchor" href="#_2-手動クイック起動項目" aria-label="Permalink to &quot;2. 手動クイック起動項目&quot;">​</a></h2><p><strong>設定 → クイック起動 → クイック起動</strong>を開くと、自分で登録した項目を管理できます。</p><ul><li>ファイル、フォルダー、URL、Windows Shell パスを追加できます。対象の確認時には環境変数も展開されます。</li><li>表示名は空欄にできます。空欄の場合、Lertaro が対象から名前を自動生成します。</li><li>ファイルとフォルダーの参照ボタンでは複数選択ができ、有効で重複しない対象がそれぞれ独立した項目として追加されます。</li><li>ドラッグハンドルで順序を変更できます。編集をクリックすると対象の行が保存・キャンセルボタン付きのインライン編集欄に変わり、削除ボタンで項目を削除できます。</li><li>手動項目では、タイルにマウスを置いて省略記号ボタンをクリックするとメニューが開き、<strong>編集</strong> または <strong>削除</strong> を選べます。<strong>編集</strong> は項目エディターのダイアログを開きます。</li><li>項目がある場合は、一覧見出しの右側にある<strong>一覧をクリア</strong>で手動項目を一括削除できます。項目がない場合、このボタンは非表示です。</li><li>現在利用できない対象はパネルから一時的に除外され、再び利用可能になると表示されます。</li></ul><h2 id="_3-データソース" tabindex="-1">3. データソース <a class="header-anchor" href="#_3-データソース" aria-label="Permalink to &quot;3. データソース&quot;">​</a></h2><p><strong>設定 → クイック起動 → データソース</strong>を開くと、動的データソースを選択できます。</p><ul><li>データソースはインストール済みのクイックパネルのタブプロバイダーから提供されます。そのため、お気に入り、履歴、Windows 履歴、前回のディレクトリ、最近使ったファイル、今後のプラグインソースを二重管理せずに再利用できます。</li><li>プロバイダーが存在するソースは既定で有効です。ユーザー設定には明示的に無効化したソースだけが保存されます。</li><li>有効で、現在データを返すソースだけがパネルのタブになります。データのないソースは非表示です。</li><li>データソースの横にあるドラッグハンドルでパネルタブの順序を変更できます。順序はクイック起動設定に保存されます。</li><li>手動項目と動的データソースのすべてにデータがない場合、クイック起動パネルは非表示になります。</li></ul><h2 id="_4-パネルの操作" tabindex="-1">4. パネルの操作 <a class="header-anchor" href="#_4-パネルの操作" aria-label="Permalink to &quot;4. パネルの操作&quot;">​</a></h2><ul><li>列数は検索バーの幅に合わせて変化します。</li><li>ソースが1つだけの場合、下部のソースインジケーターは非表示です。</li><li>複数のソースがある場合、下部にソースごとのドットが1つ表示されます。選択中は青、未選択はグレーで、ドットにマウスを置くとソース名が展開表示されます。</li><li>パネル上で <strong>Shift</strong> を押しながらマウスホイールを回すとソースを順番に切り替えられ、切り替えたソースには同じ展開アニメーションが短時間表示されます。</li><li>設定した <strong>次の項目を選択</strong> と <strong>前の項目を選択</strong> のホットキー（既定は <strong>Ctrl+N</strong> と <strong>Ctrl+P</strong>）でも、パネル表示中はソースを切り替えられます。末尾から先頭、先頭から末尾へ循環します。</li><li>パネル表示中は、方向キーで項目を見た目どおりのグリッドに沿って移動できます。<strong>←</strong> と <strong>→</strong> は行の境界を越えて移動し、<strong>↑</strong> と <strong>↓</strong> は現在の列を維持します。最後の行に対応する列の項目がない場合、上下移動は現在の項目で止まり、項目選択は循環しません。</li><li>どのソースの項目でも右クリックすると、クイック起動パネル内にその項目のフローティングアクションメニューが開きます。パネルは一時的にアクション一覧の最大作業高さまで広がり、メニューを閉じると元の高さに戻ります。メニューの外側をクリックすると閉じます。</li><li>パネル内の項目が表示領域に収まらない場合は、項目部分でマウスホイールを回して縦にスクロールできます。項目にマウスを置いてもスクロールは妨げられません。</li><li>検索語の入力を始めると、パネルは非表示になります。</li></ul>',12)])])}const _=i(o,[["render",n]]);export{c as __pageData,_ as default};
